import {cp,mkdir,rm,writeFile,readFile} from 'node:fs/promises';
import {assertReleasedGames,assertProductionInventory} from './release-policy.mjs';
import {catalog} from '../src/catalog.mjs';
import {renderPage} from '../src/render.mjs';
const root = new URL('../',import.meta.url);
await assertReleasedGames(new URL('public/',root));
const release=JSON.parse(await readFile(new URL('docs/hurdles-main/SOURCE-MANIFEST.json',root),'utf8'));
const rod=JSON.parse(await readFile(new URL('docs/reaction-rod-main/SOURCE-MANIFEST.json',root),'utf8'));
const studio=JSON.parse(await readFile(new URL('docs/studio-main/SOURCE-MANIFEST.json',root),'utf8'));
const jump=JSON.parse(await readFile(new URL('docs/long-jump-main/SOURCE-MANIFEST.json',root),'utf8'));
const fastHands=JSON.parse(await readFile(new URL('docs/fast-hands-main/SOURCE-MANIFEST.json',root),'utf8'));
const polish=JSON.parse(await readFile(new URL('docs/fast-hands-polish/SOURCE-MANIFEST.json',root),'utf8'));
const allowedPublicPaths=[...release.allowedPublicPaths,...rod.addedPublicPaths,...studio.addedPublicPaths,...jump.addedPublicPaths,...fastHands.addedPublicPaths,...polish.addedPublicPaths];
await assertProductionInventory(new URL('public/',root),allowedPublicPaths);
const html=renderPage(catalog);
await writeFile(new URL('public/index.html',root),html);
await rm(new URL('dist/',root),{recursive:true,force:true});
await mkdir(new URL('dist/',root),{recursive:true});
await cp(new URL('public/',root),new URL('dist/',root),{recursive:true});
await assertReleasedGames(new URL('dist/',root));
await assertProductionInventory(new URL('dist/',root),allowedPublicPaths);
console.log('Built static Playformosa to dist/');

import {readFile,readdir,stat} from 'node:fs/promises';
import{assertReleasedGames,assertProductionInventory}from'./release-policy.mjs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import assert from 'node:assert/strict';
const root=fileURLToPath(new URL('../dist/',import.meta.url));
async function files(dir){const entries=await readdir(dir,{withFileTypes:true});return (await Promise.all(entries.map(item=>item.isDirectory()?files(path.join(dir,item.name)):path.join(dir,item.name)))).flat();}
await assertReleasedGames(root);
const release=JSON.parse(await readFile(new URL('../docs/hurdles-main/SOURCE-MANIFEST.json',import.meta.url),'utf8'));const rod=JSON.parse(await readFile(new URL('../docs/reaction-rod-main/SOURCE-MANIFEST.json',import.meta.url),'utf8'));const studio=JSON.parse(await readFile(new URL('../docs/studio-main/SOURCE-MANIFEST.json',import.meta.url),'utf8'));const jump=JSON.parse(await readFile(new URL('../docs/long-jump-main/SOURCE-MANIFEST.json',import.meta.url),'utf8'));const fastHands=JSON.parse(await readFile(new URL('../docs/fast-hands-main/SOURCE-MANIFEST.json',import.meta.url),'utf8'));const polish=JSON.parse(await readFile(new URL('../docs/fast-hands-polish/SOURCE-MANIFEST.json',import.meta.url),'utf8'));await assertProductionInventory(root,[...release.allowedPublicPaths,...rod.addedPublicPaths,...studio.addedPublicPaths,...jump.addedPublicPaths,...fastHands.addedPublicPaths,...polish.addedPublicPaths]);
const paths=await files(root);
let checked=0;
for(const file of paths){
  if(!/\.(html|mjs|css)$/.test(file))continue;
  const source=await readFile(file,'utf8');
  const refs=file.endsWith('.html')?[...source.matchAll(/(?:src|href)="([^"]+)"/g)].map(m=>m[1]):file.endsWith('.mjs')?[...source.matchAll(/(?:from\s*|import\s*)['"](\.[^'"]+)['"]/g)].map(m=>m[1]):[...source.matchAll(/url\(['"]?([^)'"\s]+)['"]?\)/g)].map(m=>m[1]);
  for(const ref of refs){
    if(/^(?:https?:|data:|blob:|mailto:)/.test(ref))continue;
    if(ref==='#'){checked++;continue;}
    if(ref.startsWith('#')){assert.ok(new RegExp(`id=["']${ref.slice(1)}["']`).test(source),`Missing anchor ${ref} in ${file}`);checked++;continue;}
    let target=ref.startsWith('/')?path.join(root,ref):path.resolve(path.dirname(file),ref);
    target=target.split(/[?#]/)[0];
    let info;try{info=await stat(target);}catch{throw new Error(`Missing local reference ${ref} from ${path.relative(root,file)}`);}
    if(info.isDirectory())await stat(path.join(target,'index.html'));
    checked++;
  }
}
console.log(`Verified ${checked} local references across ${paths.length} output files. Browser visual/touch QA not performed.`);

import {readFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {fileURLToPath} from 'node:url';
import path from 'node:path';
import assert from 'node:assert/strict';
const root=fileURLToPath(new URL('../../',import.meta.url));
export const polishManifest=()=>JSON.parse(readFileSync(new URL('../../docs/fast-hands-polish/SOURCE-MANIFEST.json',import.meta.url),'utf8'));
const hash=b=>createHash('sha256').update(b).digest('hex');
const blob=b=>createHash('sha1').update(Buffer.concat([Buffer.from('blob '+b.length+'\0'),b])).digest('hex');
export function reversePolish(file,bytes,manifest=polishManifest()){
 assert.equal(new Set(manifest.files.map(f=>f.path)).size,manifest.files.length,'duplicate polish historical paths');
 assert.ok(!manifest.addedPaths.includes(file),file+' is a new polish file, not historical source');
 const f=manifest.files.find(f=>f.path===file);if(!f)return Buffer.from(bytes);
 assert.equal(typeof f.beforeText,'string',file+' polish prior text required');
 assert.equal(hash(bytes),f.sha256,file+' polish current bytes');assert.equal(blob(bytes),f.gitBlob,file+' polish current Git blob');
 const before=Buffer.from(f.beforeText);assert.equal(hash(before),f.beforeSha256,file+' polish prior bytes');assert.equal(blob(before),f.beforeGitBlob,file+' polish prior Git blob');return before;
}
export function readBeforePolish(file,encoding){
 const absolute=file instanceof URL?fileURLToPath(file):path.resolve(file),relative=path.relative(root,absolute).split(path.sep).join('/');
 assert.ok(relative!=='..'&&!relative.startsWith('../')&&!path.isAbsolute(relative),'historical path must remain inside repository');
 const bytes=reversePolish(relative,readFileSync(file));return encoding?bytes.toString(encoding):bytes;
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync,readdirSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {polishManifest,reversePolish,readBeforePolish} from './helpers/fast-hands-polish-provenance.mjs';
const root=new URL('../',import.meta.url),read=p=>readFileSync(new URL(p,root));
const hash=b=>createHash('sha256').update(b).digest('hex');
const blob=b=>createHash('sha1').update(Buffer.concat([Buffer.from('blob '+b.length+'\0'),b])).digest('hex');
const fixtureBytes=read('tests/fixtures/fast-hands-polish-baseline.json');
assert.equal(hash(fixtureBytes),'80987b826f9ceeeeaf7e50653f14af5626c6f773bd167befe3d92ea6f0200cd4','polish base is independently pinned to main 2857cf6');
const baseline=JSON.parse(fixtureBytes);
test('polish declares only the approved six-game upload and three-game toolbar scope',()=>{
 const m=polishManifest();assert.equal(m.baseCommit,'2857cf68e6cf45f0cbb0e7a3e63520dba60e2c41');assert.equal(m.baseTree,'8b2d255b710933b2370c950706c8299ce8d7dacf');
 assert.deepEqual(m.files.map(f=>f.path).sort(),baseline.modifiedPaths);assert.deepEqual([...m.addedPaths].sort(),baseline.addedPaths);
 assert.deepEqual(m.addedPublicPaths,['games/shared/upload-cooldown.mjs']);
 const actual=[];function walk(dir=''){for(const e of readdirSync(new URL(dir?dir+'/':'./',root),{withFileTypes:true})){const p=dir?dir+'/'+e.name:e.name;if(!dir&&['dist','node_modules','.git'].includes(e.name))continue;if(e.isDirectory())walk(p);else {assert.ok(e.isFile(),p+' must be a regular file');actual.push(p);}}}walk();
 assert.deepEqual(actual.sort(),[...baseline.files.map(f=>f.path),...baseline.addedPaths].sort(),'no unreviewed additions or deletions');
});
test('all 544 original tracked files match remote base after the exact approved delta is reversed',()=>{
 const m=polishManifest();assert.equal(baseline.files.length,544);
 for(const f of baseline.files){const before=readBeforePolish(new URL(f.path,root));assert.equal(hash(before),f.sha256,f.path);assert.equal(blob(before),f.gitBlob,f.path);}
 for(const f of m.files){const original=baseline.files.find(b=>b.path===f.path);assert.ok(original,f.path);assert.equal(f.beforeSha256,original.sha256);assert.equal(f.beforeGitBlob,original.gitBlob);}
});
test('current bytes and saved prior bytes must both validate, and additions cannot impersonate history',()=>{
 const m=polishManifest();for(const f of m.files){const bytes=read(f.path);assert.equal(blob(reversePolish(f.path,bytes,m)),f.beforeGitBlob);
  assert.throws(()=>reversePolish(f.path,Buffer.concat([bytes,Buffer.from('tamper')]),m));
  for(const field of ['beforeText','beforeSha256','beforeGitBlob','sha256','gitBlob']){const bad=structuredClone(m);bad.files.find(x=>x.path===f.path)[field]+='tamper';assert.throws(()=>reversePolish(f.path,bytes,bad),f.path+' '+field);}
  const bad=structuredClone(m);bad.files.push({...f});assert.throws(()=>reversePolish(f.path,bytes,bad));
 }
 for(const p of m.addedPaths)assert.throws(()=>reversePolish(p,read(p),m));
});
test('schema, bindings, old ledgers, original game engines and score rules stay byte-identical',()=>{
 const protectedPaths=baseline.files.filter(f=>f.path==='wrangler.jsonc'||f.path.startsWith('docs/')||f.path.endsWith('.sql')||/^public\/games\/(hurdles|long-jump|reaction-rod|javelin)\//.test(f.path)&&f.path!=='public/games/reaction-rod/leaderboard.mjs'||/^public\/games\/fast-hands\/(core|duck|levels|catch|duel)\//.test(f.path));
 assert.ok(protectedPaths.length>100);
 for(const f of protectedPaths){assert.ok(!baseline.modifiedPaths.includes(f.path),f.path);assert.equal(blob(read(f.path)),f.gitBlob,f.path);}
 for(const name of ['0001.sql','003-reaction-rod-production.sql'])assert.ok(protectedPaths.some(f=>f.path==='worker/leaderboard/'+name));
});
